      }
    },0);
  }
  var _codeRaw='';
  function checkCodeOverflow(){
    setTimeout(function(){
      if(codeWrap.scrollWidth>codeWrap.clientWidth+1){
        codeMore.style.display='inline';
      } else {
        codeMore.style.display='none';
      }
    },0);
  }
